enum Status {
    AVAILABLE(0), BORROWED(5);
    private final int dailyFee;
    Status(int dailyFee) { this.dailyFee = dailyFee; }
    int dailyFee() { return dailyFee; }
}

class Main {
    public static void main(String[] args) throws Exception {
        System.out.println(Status.BORROWED.dailyFee());
        System.out.println(Status.AVAILABLE == Status.valueOf("AVAILABLE"));
    }
}

enum Status { AVAILABLE, BORROWED }

class Main {
    public static void main(String[] args) throws Exception {
        Status status = Status.BORROWED;
        String action = switch (status) {
            case AVAILABLE -> "Borrow";
            case BORROWED -> "Return";
        };
        System.out.println(action);
    }
}

record Result(int roll, int mark) {
    Result {
        if (mark < 0 || mark > 100) { throw new IllegalArgumentException("mark"); }
    }
}

class Main {
    public static void main(String[] args) throws Exception {
        Result first = new Result(7, 80);
        Result second = new Result(7, 80);
        System.out.println(first.equals(second));
        System.out.println(first.roll() + " " + first.mark());
    }
}
